def verify():
    assert abs(0.05 + 0.4605 * 2 - 0.971) < 1e-9 and abs(0.02413 / 2 - 0.0121) < 1e-4
    assert abs(20 * 200 ** 2 / (8 * 20000) - 5) < 1e-12 and abs(8 * 25 / 600 - 0.333) < 1e-3
    assert abs(math.sqrt(3) * 100 * 4 - 692.8) < 0.1 and abs(300 / 6600 * 100 - 4.545) < 0.001
    assert abs(154000 ** 2 * 0.5 / 100 / 1e6 - 118.58) < 0.01
    E = 6600 / math.sqrt(3); assert abs(3 * 377 * 1e-6 * E - 4.31) < 0.01
    assert abs(math.sqrt(3) * 13.2 - 22.86) < 0.01 and 9.8 * 10 * 100 * 0.9 == 8820 and abs(860 / (0.25 * 8600) - 0.4) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
